import {resourceData as data,ukResourcePaths} from './resource-data.js?v=20261027-resources01';
import {developmentPaths} from './development-data.js?v=20261026-development01';
export {data as resourceData,ukResourcePaths};
export const resourceViews={
 'dev-india-management':[['treatment','Operate the whole service'],['projects','Dated project evidence'],['community','Local groups and support'],['evaluate','Judge lasting outcomes']],
 'dev-resource-types':[['classify','Two classification questions'],['balanced','Renewal matches use'],['heavy','Use exceeds renewal'],['finite','A finite stock']],
 'dev-resource-exploitation':[['water','Abstract water'],['fossil','Extract fossil fuel'],['fish','Harvest fish'],['farm','Produce food'],['forest','Convert forest land']],
 'dev-resource-impacts':[['habitat','Habitat connections'],['erosion','Exposed soil and runoff'],['water','Water-quality pathways'],['air','Dust, combustion and climate']],
 'dev-resource-distribution':[['forests','World forest evidence'],['world','Selected world examples'],['uk','UK resource examples'],['controls','From presence to access']]
};
export const resourceRequirements=Object.fromEntries(Object.entries(resourceViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const resourceAnimated=(k,v)=>k==='dev-india-management'?['treatment','community'].includes(v):k==='dev-resource-types'?v!=='classify':k==='dev-resource-exploitation'?true:k==='dev-resource-impacts'?v!=='habitat':false;
export const resourceBalance=(start,renew,remove)=>start+renew-remove;
export const forestBin=v=>v==null?-1:v<10?0:v<30?1:v<50?2:3;
export const ukResourceXY=(lon,lat)=>[20+(lon+13)/22*250,65+(61-lat)/12*235];
const readable=s=>String(s).replace(/([A-Za-z])(?=\d)/g,'$1 ').replace(/(\d)(?=[A-Za-z])/g,'$1 ');
const T=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${readable(s)}</text>`;
const line=(d,c='#b4cbd0',w=2)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=5,c='#edb396')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#eee8d7"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?64:40}" rx="10" fill="#35566b" stroke="#a2bec7"/>`+T(x+10,y+24,a,12)+(b?T(x+10,y+47,b,11):'');
const title=s=>T(20,29,s,13);
const fig=(b,c)=>`<svg viewBox="0 0 440 350" style="background:#203e53;border-radius:12px" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#f0f1e9" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,s)=>`<a href="${u}" target="_blank" rel="noopener">${s}</a>`;
const source=k=>`<p class="geo-caption">${{
 projects:link(data.gange.source,'Jal Shakti,23 March2026:programme status')+'. Snapshot February2026; sanctioned524/completed355 programme projects. Counts are not river area cleaned or a measured health effect.',
 management:link(data.gange.source,'Namami Gange official status')+' · '+link('https://www.worldbank.org/en/results/2020/10/16/unleashing-the-power-of-women-collectives-for-rural-development-in-the-indian-state-of-bihar','World Bank:Bihar JEEViKA,2020')+'. Government/project sources describe delivery and roles; not universal independent outcomes or equal representation.',
 limits:link('https://www.fisheries.noaa.gov/national/population-assessments/fish-stock-sustainability','NOAA:fish stock sustainability')+' · '+link('https://www.fao.org/newsroom/detail/Saving-our-soils/','FAO:slowly replaceable soil')+'. Stock examples are invented teaching quantities, not fisheries or aquifer assessments.',
 impacts:link('https://www.fao.org/newsroom/detail/Saving-our-soils/','FAO:soil functions and degradation')+' · '+link('https://www.pib.gov.in/Pressreleaseshare.aspx?PRID=1809239&lang=2&reg=48','Jal Shakti:pollution pathways')+'. Processes are symbolic, not measured concentrations, ecological recovery times or forecasts.',
 forests:link(data.forest.source,'WDI / FAO:forest area definition')+' · '+link('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth public-domain geometry')+'.2023 forest%land area; API8October2026; WDI CC BY4.0. Six selected countries; grey not selected. Not timber output, condition or logging rights.',
 uk:link('https://www.ons.gov.uk/economy/environmentalaccounts/bulletins/enclosedfarmlandnaturalcapitalaccountsuk/2026','ONS2026:2024 farmland patterns')+' · '+link('https://www.metoffice.gov.uk/research/climate/maps-and-data/regional-climates','Met Office:regional climate context')+' · '+link('https://www.gov.scot/publications/scotlands-fourth-land-use-strategy-supporting-evidence-pack/pages/4/','Scotland:2024 woodland evidence')+' · '+link('https://earthwise.bgs.ac.uk/index.php/South-west_England_area_-_Geology','BGS:southwest geology and clay')+' · '+link('https://www.nstauthority.co.uk/what-we-do/energy-production-and-security/','NSTA:offshore resources')+'. Actual generalised outlines; approximate examples, not resource extents or licence boundaries. Rainfall does not measure delivered usable water.',
 world:link('https://www.usgs.gov/centers/national-minerals-information-center/chile','USGS:Chile mineral resources')+' · '+link('https://www.eia.gov/international/analysis/country/sau','EIA:Saudi Arabia oil')+' · '+link('https://www.canada.ca/en/environment-climate-change/services/science-technology/changing-climate-report-2026/cccr-chapter-5-en.html','Canada:freshwater systems')+' · '+link('https://www.ars.usda.gov/ARSUserFiles/50600000/Products-Reprints/2003/1069.pdf','USDA:Great Plains soils/crops')+' · '+link(data.forest.source,'WDI/FAO:forests')+'. Selected examples locate different resource systems, not complete deposits, measured reserves or current extraction rates.'
 }[k]}</p>`.split(/(<[^>]*>)/g).map(part=>part.startsWith('<')?part:readable(part)).join('');
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${cap}</caption><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
const forestColours=['#ead1ae','#c7c99d','#91b49a','#527f79'];
const fv=n=>n<.01?n.toFixed(4):n.toFixed(1);
export function resourceEvidence(k='forests'){
 if(k==='projects'){let b=title('NAMAMI GANGE · PROGRAMME PROJECT COUNTS')+T(20,54,'February2026 · zero-based count scale',11);for(const[i,[n,v]]of [['Sanctioned',524],['Completed',355]].entries()){const y=105+i*100;b+=T(20,y,n,14)+`<rect x="20" y="${y+14}" width="${v/550*340}" height="30" rx="4" fill="${i?'#a8c2af':'#edb396'}"/>`+T(30+v/550*340,y+35,String(v),12);}b+=T(20,326,'Same programme and snapshot; read what is counted.',11);return fig(b,'Reported sanctioned and completed programme projects in the same February2026 snapshot. Use the count denominator and date before comparing.')+source('projects')+table('Programme projects as of February2026',['Status','Count'],[['Sanctioned',524],['Completed',355]]);}
 if(k==='uk'){let b=title('UK · SELECTED RESOURCE EXAMPLES')+T(20,51,'North ↑ · generalised outlines · dots are locators',11)+`<defs><clipPath id="r1-uk-clip"><rect x="20" y="65" width="250" height="235"/></clipPath></defs><rect x="20" y="65" width="250" height="235" fill="#244c61"/><g clip-path="url(#r1-uk-clip)">${ukResourcePaths.map(p=>`<path d="${p.d}" fill="${p.code==='GBR'?'#b6c2a5':'#648985'}" stroke="#dce4d6" stroke-width="0.8"/>`).join('')}</g>`;for(const[i,[n,lon,lat]]of data.ukProjection.markers.entries()){const[x,y]=ukResourceXY(lon,lat);b+=dot(x,y,9)+`<text x="${x}" y="${y+3}" text-anchor="middle" font-size="10" fill="#19364b">${i+1}</text>`+T(286,91+i*45,(i+1)+'. '+n,11);}b+=T(20,327,'Examples are not boundaries, quantities or all UK sites.',11);return fig(b,'Real country geometry reprojected to a regional UK view with five approximate resource examples. Read the numbered key; markers are not deposit outlines, field boundaries or reserves.')+source('uk');}
 if(k==='world'){let b=title('WORLD · SELECTED RESOURCE SYSTEMS')+T(20,51,'North ↑ · generalised world outlines',11);for(const p of developmentPaths)b+=`<path d="${p.d}" fill="#6b918b" stroke="#234355" stroke-width="0.5"/>`;const pts=[['Saudi Arabia:oil',45,24],['Chile:minerals',-70,-24],['Brazil:forests',-60,-5],['Canada:freshwater',-85,50],['Great Plains:soil/crops',-100,40]];for(const[i,[n,lon,lat]]of pts.entries()){const x=20+(lon+180)/360*400,y=55+(85-lat)/145*200;b+=dot(x,y,7)+`<text x="${x}" y="${y+3}" text-anchor="middle" font-size="9" fill="#19364b">${i+1}</text>`+T(20+i%2*220,278+Math.floor(i/2)*26,(i+1)+'. '+n,11);}return fig(b,'Actual world outlines and five approximate resource locators. These show selected examples, not complete global resource distribution, exact deposits or quantities.')+source('world');}
 let b=title('FOREST AREA · SIX SELECTED COUNTRIES')+T(20,51,'2023 · percent of land area · grey = not selected',11);for(const p of developmentPaths){const v=data.forest.countries.find(x=>x.code===p.code)?.value;b+=`<path d="${p.d}" fill="${v==null?'#697e86':forestColours[forestBin(v)]}" stroke="#234355" stroke-width="0.5"/>`;}const keys=['<10%','10–<30%','30–<50%','≥50%'];for(let i=0;i<4;i++)b+=`<rect x="${20+i*103}" y="275" width="15" height="15" fill="${forestColours[i]}"/>`+T(40+i*103,287,keys[i],10);b+=T(20,326,'Percent land under forest; not a map of timber output.',11);return fig(b,'Real Natural Earth country shapes joined to a dated six-country WDI/FAO extract. Colours show forest share of land area using the labelled bins; grey countries are outside this selection.')+source('forests')+table('2023 forest area as percent of land area; rounded display',['Country','Forest %'],data.forest.countries.map(x=>[x.name,fv(x.value)]));
}
export function resourceScene(k,v,t=0){if(!resourceViews[k])return '';if(!resourceRequirements[k].includes(v))v=resourceRequirements[k][0];t=resourceAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',s='limits';if(k==='dev-india-management'&&v==='projects')return resourceEvidence('projects');if(k==='dev-resource-distribution'&&v!=='controls')return resourceEvidence(v);
 if(k==='dev-india-management'){s='management';
 if(v==='treatment'){b=title('OPERATE THE WHOLE POLLUTION-CONTROL SERVICE')+box(20,65,180,'Collect wastewater','Connections / reliable flow')+box(240,65,180,'Treat and maintain','Staff / energy / repairs')+box(120,245,200,'Check actual outcomes','Water quality / access')+line('M200 100H233M330 138L250 235')+dot(200+33*t,100)+dot(330-80*t,138+97*t)+T(20,329,'Namami Gange:outputs do not prove every outcome.',11);c='A conceptual service-and-monitoring sequence, not a measured river flow or guaranteed health benefit. Source control, collection, operation and upkeep affect outcomes.';}
 else if(v==='community'){b=title('LOCAL KNOWLEDGE + WIDER CAPACITY')+box(20,65,180,'Women’s groups','Priorities / savings / voice')+box(240,65,180,'Supporting institutions','Finance / training / markets')+box(120,245,200,'Useful local opportunities','Evaluate who participates')+line('M200 100H233M330 138L250 235M120 275L80 138')+dot(200+33*t,100)+dot(330-80*t,138+97*t)+dot(120-40*t,275-137*t)+T(20,330,'Bihar JEEViKA illustrates roles, not universal gains.',11);c='A conceptual participation-and-support loop linked to JEEViKA’s documented roles. Local groups need inclusive representation and continuing capability; token timing is not a measured income effect.';}
 else{b=title('JUDGE QUALITY OF LIFE AND WIDER STATUS')+box(20,65,400,'Delivery:what exists and operates?','Projects / staff / maintenance / access')+box(20,153,400,'Outcomes:what improved, for whom?','Water quality / livelihoods / inclusion / costs')+box(20,241,400,'Wider standing:what can be sustained?','Credibility / capability / cooperation');c='A static evaluation framework. Effective management can support quality of life and international credibility, but no single project count measures national status.';}
 }
 if(k==='dev-resource-types'){
 if(v==='classify'){b=title('TWO DIFFERENT CLASSIFICATION QUESTIONS')+box(20,65,190,'Biotic examples','Fish / trees')+box(230,65,190,'Abiotic examples','Water / mineral ores')+box(20,180,190,'Potentially renewable','Fish / timber / fresh water')+box(230,180,190,'Finite geological stocks','Ore / fossil fuels')+T(20,296,'Living/non-living and renewal are different axes.',11)+T(20,326,'Renewal depends on rate, place, quality and management.',10);c='Selected unambiguous classifications. Fossil-fuel origin is not used for a contested biotic/abiotic test; soil is a complex slowly formed resource, not a simple unlimited stock.';}
 else{const finite=v==='finite',renew=finite?0:20,take=v==='heavy'?35:20,ending=resourceBalance(100,renew,take),stock=100+(ending-100)*t;b=title(finite?'FINITE STOCK · NO RAPID REPLACEMENT':v==='heavy'?'REMOVAL EXCEEDS RENEWAL':'RENEWAL MATCHES REMOVAL')+T(20,64,'Invented stock balance · teaching units',12)+`<rect x="70" y="100" width="300" height="80" rx="8" fill="#29495c" stroke="#adc7c8"/><rect x="70" y="100" width="${stock*3}" height="80" rx="8" fill="#a9c4b0"/>`+`<text x="85" y="147" fill="#19364b" font-size="19">Stock: ${stock.toFixed(0)}</text>`+line('M375 140H420')+dot(375+45*t,140)+T(325,91,'Use: '+take,11)+(finite?'':line('M20 140H65')+dot(20+45*t,140)+T(20,91,'Renew: '+renew,11))+T(20,220,`Start100 +renewal${renew} −removal${take}`,14)+T(20,258,'End:'+ending+' units',17)+line('M50 292H180')+dot(50+130*t,292)+T(195,298,finite?'Extraction':'Renewal / harvest',12)+T(20,332,'Loop repeats the explanation; it does not reset a real stock.',10);c=finite?'A finite fossil-stock teaching example:100−20=80 and no meaningful replacement during this human-scale interval. Playback restarting does not regenerate geological fuels.':'A simplified renewable-stock balance with fixed assumed renewal and removal. Real stocks have variable reproduction, habitat and conditions; this is not a fishery forecast.';}
 }
 if(k==='dev-resource-exploitation'){
 if(v==='water'){b=title('ABSTRACTION MOVES WATER FROM A LOCAL STORE')+`<path d="M30 205H420V300H30Z" fill="#6595a5"/><path d="M30 170Q190 140 420 170V205H30Z" fill="#b2b697"/>`+line('M120 250V95H310','#c6d7d1',7)+dot(120,250-155*t)+dot(120+190*t,95)+box(235,40,185,'Distribution / use','Treatment and storage')+T(40,270,'Aquifer / local store',14)+T(20,331,'Store balance:100+20recharge−30abstraction=90.',11);c='Conceptual water pumping and distribution, not a measured aquifer, pumping depth or water loss from Earth. The invented store declines if abstraction exceeds recharge.';}
 else if(v==='fossil'){b=title('EXTRACT AND PROCESS A GEOLOGICAL STOCK')+`<path d="M20 160H420V300H20Z" fill="#7b8d8d"/><ellipse cx="120" cy="255" rx="65" ry="25" fill="#213a48"/>`+line('M120 250V85H300','#d4c6ad',6)+dot(120,250-165*t,5,'#d2b18e')+dot(120+180*t,85,5,'#d2b18e')+box(250,35,170,'Process / use','Not rapid replenishment')+T(50,263,'Fuel deposit',13)+T(20,331,'Extraction rate is illustrative; geology is not to scale.',11);c='A symbolic extraction pathway. Fossil fuel is removed from an existing geological stock; the loop does not show new oil forming each cycle.';}
 else if(v==='fish'){b=title('HARVEST ORGANISMS FROM A RENEWING STOCK')+`<rect x="20" y="105" width="400" height="190" rx="10" fill="#386780"/>`+Array.from({length:14},(_,i)=>`<ellipse cx="${50+i%7*52}" cy="${155+Math.floor(i/7)*70}" rx="10" ry="5" fill="#c2d2bd"/>`).join('')+`<path d="M300 70H390L370 95H320Z" fill="#e1b99b"/><path d="M320 98L${270+35*t} 230H${370-20*t}L370 98" fill="none" stroke="#e0d6bd" stroke-width="2"/>`+dot(330,210-110*t)+T(20,50,'Removal and reproduction must be assessed together.',11)+T(20,331,'Conceptual catch, not actual stock size or capture rate.',11);c='Illustrative capture from a fish stock. Reproduction and habitat can support replenishment, but harvest can exceed that capacity; fish icons are not population data.';}
 else if(v==='farm'){b=title('FARMING COMBINES LAND, WATER AND GROWTH')+`<rect x="20" y="180" width="400" height="115" fill="#8eaa8c"/>`+Array.from({length:8},(_,i)=>line(`M${55+i*45} 270V${230-t*50}m0 20l-10-12m10 5 10-12`,'#e1d5a2',3)).join('')+box(20,65,190,'Soil / water / nutrients','Inputs and conditions')+box(230,65,190,'Crops / livestock','Food production')+T(20,329,'Growth sequence is symbolic, not a measured yield forecast.',10);c='A conceptual crop-growth example representing biological production. Farming methods and outcomes vary; input increases do not remove soil, water or ecological limits.';}
 else{b=title('DEFORESTATION CONVERTS FOREST TO OTHER USE')+`<rect x="20" y="95" width="400" height="200" fill="#758f80"/>`+Array.from({length:15},(_,i)=>{const cut=i<Math.floor(t*15),x=50+i%5*78,y=130+Math.floor(i/5)*55;return cut?`<rect x="${x-18}" y="${y}" width="38" height="24" fill="#d3bd93"/>`:`<path d="M${x} ${y-20}l-19 36h38Z" fill="#c0d0b3"/>`;}).join('')+T(20,65,'Forest → agricultural land in this example',13)+T(20,331,'Not every timber harvest is permanent land-use conversion.',10);c='A schematic forest-to-farmland conversion, not actual clearing geometry, area or rate. The loop resets a teaching scene; it does not recreate an old-growth habitat.';}
 }
 if(k==='dev-resource-impacts'){s='impacts';
 if(v==='habitat'){b=title('HABITAT LOSS AND FRAGMENTATION DIFFER')+`<rect x="30" y="75" width="160" height="180" rx="12" fill="#7eac92"/><rect x="250" y="75" width="160" height="180" rx="12" fill="#7eac92"/><path d="M220 60V280" stroke="#c5b89c" stroke-width="30"/>`+T(55,165,'Habitat patch',13)+T(270,165,'Habitat patch',13)+line('M170 215H270','#edb396',3)+T(20,315,'A barrier can interrupt connections between remaining areas.',10);c='Conceptual separated habitat patches, not real species ranges or a universal biodiversity response. Some habitat can remain while connections are disrupted.';}
 else if(v==='erosion'){b=title('EXPOSED SOIL → RUNOFF → SEDIMENT TRANSFER')+`<path d="M20 100L310 260V300H20Z" fill="#a7ad8f"/><path d="M310 260Q365 230 420 265" fill="none" stroke="#87b9c5" stroke-width="23"/>`+line('M70 120L300 247','#d6c3a0',4)+dot(70+230*t,120+127*t,5,'#dbbb8f')+Array.from({length:5},(_,i)=>line(`M${60+i*45} ${55+t*35}l-5 14`,'#b9dce3',2)).join('')+T(20,330,'Soil leaves the slope; downstream effects depend on conditions.',10);c='Illustrative rainfall/runoff transport of exposed soil. Sediment transfer is not identical to every dissolved pollutant or a measured erosion rate.';}
 else if(v==='water'){b=title('DISTINCT MATERIALS CAN REACH WATER')+box(20,65,180,'Disturbed land','Loose sediment')+box(240,65,180,'Farms / extraction / waste','Dissolved materials / effluent')+`<path d="M30 285Q200 250 420 285" fill="none" stroke="#8bb9c7" stroke-width="22"/>`+line('M110 138L180 265M330 138L280 265')+dot(110+70*t,138+127*t,5,'#d8bd94')+dot(330-50*t,138+127*t,5,'#b6cba9')+T(20,330,'Different pathways need appropriate water-quality evidence.',10);c='Possible sediment and dissolved/effluent pathways. Amounts, toxicity, dilution and treatment vary; moving dots are neither measured concentrations nor proof of identical effects.';}
 else{b=title('AIR QUALITY AND CLIMATE ARE DIFFERENT EFFECTS')+box(20,65,190,'Extraction / transport','Dust / machinery emissions')+box(230,65,190,'Fuel combustion','Air pollutants / greenhouse gases')+box(20,250,190,'Local exposure','Air-quality evidence')+box(230,250,190,'Wider climate effects','Emissions accounting')+line('M115 140V240M325 140V240')+dot(115,140+100*t,5,'#d0b894')+dot(325,140+100*t,5,'#b8cfbf')+T(20,334,'Symbolic pathways; not one shared concentration or footprint.',10);c='A causal distinction, not atmospheric modelling. Activities can contribute to both local air pollution and greenhouse-gas emissions, measured with different indicators.';}
 }
 if(k==='dev-resource-distribution'){s='world';b=title('FROM PHYSICAL PRESENCE TO USEFUL SUPPLY')+box(20,65,190,'Physical endowment','Geology / climate / soil / water')+box(230,65,190,'Technical / economic access','Costs / investment / infrastructure')+box(20,200,190,'Social / environmental limits','Protection / rights / quality')+box(230,200,190,'Usable supply and benefit','Trade / services / distribution')+T(20,326,'Resources do not guarantee self-sufficiency or equal wealth.',10);c='A static access framework. Physical distribution and the ability to use a resource are different; resource-rich locations can still face costs, shortages or unequal benefits.';}
 return fig(b,c)+source(s);
}
